// ══════════════════════════════════════════════════════════════════
// i18n.rs — traductions du CONTENU visible des pages du site (par
// opposition a function::get_user_language/SUPPORTED_LANGS, qui ne fait
// que RESOUDRE quelle langue utiliser -- ce module fournit le texte
// reellement affiche pour cette langue). Meme principe que
// clients/vex-cloudsync/src/i18n.rs (l'app cliente), mais separe : deux
// projets, deux binaires, pas de code partage possible facilement.
//
// Usage type dans un handler de page :
//   let langue = crate::function::get_user_language(pool, user_id, None, Some(&accept_lang));
//   let html = html.replace("{{T_TITRE_LOGIN}}", t(&langue, Cle::LoginTitre));
//
// Pour le JS embarque dans une page, voir `injecter_i18n_js` : genere un
// objet `const I18N = {...}` a placer dans le <script>, pour eviter de
// dupliquer le mecanisme de placeholder HTML a l'interieur du JS.
// ══════════════════════════════════════════════════════════════════

