/// Remplace chaque placeholder HTML ("{{T_XXX}}") par sa traduction dans
/// `langue`. Usage : `appliquer_traductions(html, &langue, &[("{{T_TITRE}}", Cle::Titre), ...])`.
pub fn appliquer_traductions(html: &str, langue: &str, paires: &[(&str, Cle)]) -> String {
    let mut sortie = html.to_string();
    for (placeholder, cle) in paires {
        sortie = sortie.replace(placeholder, t(langue, *cle));
    }
    sortie
}

/// Genere `const I18N = {...};` (echappement JSON correct des guillemets/
/// caracteres speciaux) pour injecter des traductions dans un `<script>`
/// existant, sans dupliquer le mecanisme de placeholder HTML a l'interieur
/// du JS -- le JS reference ensuite `I18N.CLE` au lieu d'une chaine figee.
pub fn objet_js(langue: &str, paires: &[(&str, Cle)]) -> String {
    let mut obj = serde_json::Map::new();
    for (nom, cle) in paires {
        obj.insert(nom.to_string(), serde_json::Value::String(t(langue, *cle).to_string()));
    }
    format!("const I18N = {};", serde_json::Value::Object(obj))
}
